// 1. Obtener catálogo de CISA KEV (para detectar explotación activa)
const cisaNodeData = $('Fetch_CISA_KEV').first().json;
const cisaCatalog = cisaNodeData.vulnerabilities || [];

return items.map(inputItem => {
    const item = inputItem.json;

    // Si no hay asset_name es porque el JOIN de Postgres no encontró el activo en tu inventario
    if (!item.asset_name) return null; 

    // --- 1. LÓGICA DE VERSIONES (Tu código original) ---
    const vData = item.vulnerabilities || {};
    const miVersion = item.version || "0.0.0";
    const parcheVersion = vData.first_patched_version;

    // N8N-04 (docs/22-08-26/AUDITORIA_END_TO_END.md): localeCompare({numeric:true}) no es
    // semver real -- fallaba en casos como "1.9" vs "1.10" (localeCompare los trata como
    // 1.9 > 1.10) y no entendia sufijos "v"/prerelease ("v2.0" vs "2.0.0", "1.2.0-beta").
    // compareVersions hace lo mismo que localeCompare hacia bien (comparar numero a
    // numero) pero ademas normaliza el prefijo "v" y trata un prerelease como menor que
    // la misma version sin sufijo (regla estandar de semver).
    function compareVersions(a, b) {
        const parse = (v) => {
            const clean = String(v).trim().replace(/^v/i, "");
            const [release, prerelease] = clean.split("-", 2);
            const parts = release.split(".").map((p) => parseInt(p, 10) || 0);
            return { parts, prerelease: prerelease || null };
        };
        const pa = parse(a);
        const pb = parse(b);
        const len = Math.max(pa.parts.length, pb.parts.length);
        for (let i = 0; i < len; i++) {
            const na = pa.parts[i] || 0;
            const nb = pb.parts[i] || 0;
            if (na !== nb) return na < nb ? -1 : 1;
        }
        if (pa.prerelease && !pb.prerelease) return -1;
        if (!pa.prerelease && pb.prerelease) return 1;
        if (pa.prerelease && pb.prerelease) return pa.prerelease.localeCompare(pb.prerelease);
        return 0;
    }

    let esVulnerableReal = true;
    if (parcheVersion && miVersion !== "0.0.0") {
        // Si la versión instalada ya es igual o mayor a la que trae el parche, ya no es vulnerable
        if (compareVersions(miVersion, parcheVersion) >= 0) {
            esVulnerableReal = false; 
        }
    }
    if (!esVulnerableReal) return null;

    // Fase 8 (docs/21-08-26/Plan_Implementacion_Tracking_Solido.md), Componente D: un
    // advisory retirado por GitHub despues de publicado ya no debe sostener un hallazgo
    // abierto -- se trata igual que "ya no es vulnerable" (Seccion 7.2 del marco de
    // tracking de remediacion: el quinto motivo de desaparicion de un hallazgo es "el
    // advisory cambio").
    if (item.withdrawn_at) return null;

    // --- 2. EXTRACCIÓN DE DATOS TÉCNICOS ---
    const cvssScore = parseFloat(
        item.cvss_severities?.cvss_v4?.score || 
        item.cvss_severities?.cvss_v3?.score || 
        0.0
    );
    // Fix CVE-NULL (docs/bitacora/24-08-26/AUDITORIA_END_TO_END.md): antes, dos advisories
    // GHSA-only (sin CVE) sobre el mismo componente quedaban ambas con cve_id="N/A" y
    // colisionaban en la misma fila (UNIQUE(software_component_id, cve_id) en asset_vulnerabilities).
    // Usar el propio ghsa_id como respaldo evita la colision sin requerir migracion de base.
    const idGhsa = item.ghsa_id || "N/A";
    const idCve = item.cve_id || idGhsa;

    // Match con CISA KEV
    const cisaMatch = (idCve !== "N/A") 
        ? cisaCatalog.find(v => v.cveID?.trim().toUpperCase() === idCve.trim().toUpperCase()) 
        : null;
    const esExplotado = !!cisaMatch;

    // --- 3. MATRIZ DE RIESGO CONTEXTUAL ---
    let prioridadBase = "LOW";
    if (cvssScore >= 9.0) prioridadBase = "CRITICAL";
    else if (cvssScore >= 7.0) prioridadBase = "HIGH";
    else if (cvssScore >= 4.0) prioridadBase = "MEDIUM";

    const criticidadNegocio = item.env_criticality || "LOW";
    const entornoNombre = item.env_name || "DESCONOCIDO";
    let prioridadFinal = prioridadBase;

    // Ajuste de Prioridad según el Entorno (Lógica de Tesis)
    if (criticidadNegocio === "CRITICAL") {
        if (prioridadBase === "HIGH") prioridadFinal = "CRITICAL";
        if (prioridadBase === "MEDIUM") prioridadFinal = "HIGH";
    } else if (criticidadNegocio === "LOW") {
        if (prioridadBase === "CRITICAL") prioridadFinal = "HIGH";
        if (prioridadBase === "HIGH") prioridadFinal = "MEDIUM";
    }

    // --- 4. OVERRIDES DE SEGURIDAD ---
    // Si es CISA KEV: Escala a Crítico en PROD/QA y Alto en DESA
    if (esExplotado) {
        prioridadFinal = (criticidadNegocio === "LOW") ? "HIGH" : "CRITICAL";
    }

    // Si es Zero-Day (No hay parche disponible), subimos la urgencia un nivel
    const esZeroDay = !parcheVersion;
    if (esZeroDay) {
        if (prioridadFinal === "HIGH") prioridadFinal = "CRITICAL";
        else if (prioridadFinal === "MEDIUM") prioridadFinal = "HIGH";
        else if (prioridadFinal === "LOW") prioridadFinal = "MEDIUM";
    }

    // --- 5. ACTION PLAN CONTEXTUALIZADO ---
    let plan = "";
    if (esExplotado) {
        plan = `🚨 EMERGENCIA (CISA KEV) en ${entornoNombre}: Explotación activa detectada. AISLAR '${item.asset_name}' y aplicar parche v${parcheVersion || 'URGENTE'}.`;
    } 
    else if (esZeroDay) {
        plan = `💀 ZERO-DAY en ${entornoNombre}: No existe parche para '${item.software}'. Mitigar con reglas de red y monitoreo en '${item.asset_name}'.`;
    }
    else if (prioridadFinal === "CRITICAL") {
        plan = `⚠️ PRIORIDAD MÁXIMA: Activo crítico en ${entornoNombre}. Remediación requerida en menos de 24hs.`;
    }
    else {
        plan = `🔍 TRIAGE: Riesgo ${prioridadFinal.toLowerCase()} en ${entornoNombre}. Actualizar a v${parcheVersion} según ventana de mantenimiento.`;
    }

    // --- 6. SALIDA FINAL ---
    // Fase 6 (docs/21-08-26/Plan_Implementacion_Tracking_Solido.md), Componente C:
    // desglose de las variables que produjeron `priority`, para que el backend lo
    // persista y quede auditable por que un caso quedo en tal prioridad -- antes
    // solo se guardaba la etiqueta final (prioridadFinal), nunca el detalle.
    const priorityVariables = JSON.stringify({
        cvss_score: cvssScore,
        env_criticality: criticidadNegocio,
        priority_base: prioridadBase,
        is_cisa_kev: esExplotado,
        is_zero_day: esZeroDay,
        priority_final: prioridadFinal
    });

    // Fase 8, Componente D: GHSA separa advisories revisadas (validadas por una persona)
    // de no revisadas (sincronizadas automaticamente desde NVD, con rangos a veces
    // placeholder tipo ">= 0"). El backend usa esto para no tratar un cierre automatico
    // respaldado por un advisory no revisado como verificacion fuerte.
    const advisoryType = (item.type || "unreviewed").toUpperCase();
    const vulnerableVersionRange = vData.vulnerable_version_range || null;

    return {
        json: {
            asset_id: item.id,
            asset_name: item.asset_name,
            software: item.software,
            ecosystem: item.ecosystem,
            version_instalada: miVersion,
            patch_version: parcheVersion || "N/A",
            environment: entornoNombre,
            ghsa_id: idGhsa,
            cve_id: idCve,
            cvss: cvssScore,
            priority: prioridadFinal,
            is_cisa_kev: esExplotado,
            is_zero_day: esZeroDay,
            action_plan: plan,
            priority_variables: priorityVariables,
            advisory_type: advisoryType,
            vulnerable_version_range: vulnerableVersionRange,
            processed_at: new Date().toISOString()
        }
    };
}).filter(x => x !== null);

// N8N-02 (docs/20-08-26/AUDITORIA_END_TO_END_2.md): antes un item con error de
// Fetch_GitHub_Advisories se logueaba en system_errors (Log_Advisory_Fetch_Error) y ahi
// se perdia -- nunca llegaba a Compute_Audit_Metrics, asi que un rate-limit total de
// GitHub no dejaba ningun rastro en las metricas del propio ScanReport, que terminaba
// reportando "ESTABLE" con 0 vulnerabilidades como si el escaneo hubiera evaluado todo
// y no hubiera encontrado nada. Este nodo marca el item para que Compute_Audit_Metrics
// lo cuente como "no evaluado", distinto de "sin hallazgos".
return items.map(item => ({
    json: {
        ...item.json,
        advisory_fetch_error: true
    }
}));

const allItems = items;

let metrics = {
    total_items: allItems.length,
    auditados: 0,
    ignorados: 0,
    no_evaluados: 0,
    criticos: 0,
    altas: 0,
    medias: 0,
    bajas: 0
};

// Objeto para agrupar las estadisticas por entorno
let stats_por_entorno = {};

for (const item of allItems) {
    const data = item.json;

    // N8N-02 (docs/20-08-26/AUDITORIA_END_TO_END_2.md): un item marcado por
    // Mark_Advisory_Fetch_Error nunca llego a evaluarse contra GitHub Advisory -- no es
    // "sin vulnerabilidades" (ignorado), es "no se pudo evaluar". Contarlo como ignorado
    // hacia que un rate-limit total de GitHub reportara ESTABLE en vez de avisar que
    // el escaneo quedo incompleto.
    if (data.advisory_fetch_error === true) {
        metrics.no_evaluados++;
        continue;
    }

    // Detectamos la prioridad (soporta varias fuentes de nombre)
    const rawPriority = data.priority || data.Priority || data.criticality || null;
    // Detectamos el entorno
    const envName = data.environment || data.env_name || "DESCONOCIDO";

    // Si encontramos una prioridad, el item fue analizado por el motor de riesgo
    if (rawPriority !== null) {
        metrics.auditados++;
        const sev = rawPriority.toString().toUpperCase();

        // 1. Inicializar el entorno en el objeto si no existe
        if (!stats_por_entorno[envName]) {
            stats_por_entorno[envName] = { 
                criticos: 0, 
                altas: 0, 
                medias: 0, 
                bajas: 0, 
                total: 0 
            };
        }

        // 2. Sumar al contador del entorno especifico
        stats_por_entorno[envName].total++;

        // 3. Clasificar por severidad (Global y por Entorno)
        if (sev === 'CRITICAL') {
            metrics.criticos++;
            stats_por_entorno[envName].criticos++;
        } 
        else if (sev === 'HIGH') {
            metrics.altas++;
            stats_por_entorno[envName].altas++;
        } 
        else if (sev === 'MEDIUM') {
            metrics.medias++;
            stats_por_entorno[envName].medias++;
        } 
        else if (sev === 'LOW') {
            metrics.bajas++;
            stats_por_entorno[envName].bajas++;
        }
    } 
    // Si no tiene prioridad, es porque fue filtrado/ignorado antes del motor de riesgo
    else {
        metrics.ignorados++;
    }
}

// N8N-02: un escaneo con paquetes no evaluados por una falla de GitHub Advisory nunca
// deberia reportarse como estable -- aunque no haya criticos, el resultado es incompleto.
let status_sistema;
if (metrics.criticos > 0) status_sistema = "\u26a0\ufe0f ACCI\u00d3N REQUERIDA";
else if (metrics.no_evaluados > 0) status_sistema = "\u26a0\ufe0f PARCIAL (GitHub Advisory fall\u00f3)";
else status_sistema = "\u2705 ESTABLE";

const resumenBase = `An\u00e1lisis finalizado: ${metrics.total_items} registros evaluados.`;
const resumen = metrics.no_evaluados > 0
    ? `${resumenBase} ${metrics.no_evaluados} paquete(s) no se pudieron evaluar por un error al consultar GitHub Advisory (ver system_errors).`
    : resumenBase;

return [{
    json: {
        ejecucion_stats: {
            resumen,
            detalle: metrics,
            entornos: stats_por_entorno,
            status_sistema,
            fecha: new Date().toLocaleString('es-AR')
        }
    }
}];

// Red de seguridad: garantiza que Persist_Scan_Statistics siempre reciba
// datos, incluso cuando el paquete escaneado no tiene ninguna advisory en
// GitHub (caso legitimo y frecuente -- la mayoria del software no tiene
// CVEs activos). Sin esto, Fetch_GitHub_Advisories -> Extract_Advisory_Items
// se queda con 0 items y toda la cadena de enriquecimiento nunca llega a
// Compute_Audit_Metrics, dejando el ScanReport trabado en RUNNING para
// siempre. Se alimenta directo de Edit Fields (1 item garantizado, corre en
// paralelo a la cadena real) para no tocar la logica de matching -- se
// marca isFallback para que Pick_Real_Or_Fallback_Metrics lo descarte si la
// cadena real SI encontro datos.
return [{
    json: {
        isFallback: true,
        ejecucion_stats: {
            resumen: 'Análisis finalizado: 0 vulnerabilidades encontradas para el alcance solicitado.',
            detalle: {
                total_items: 0,
                auditados: 0,
                ignorados: 0,
                criticos: 0,
                altas: 0,
                medias: 0,
                bajas: 0
            },
            entornos: {},
            status_sistema: '✅ ESTABLE',
            fecha: new Date().toLocaleString('es-AR')
        }
    }
}];

// Choose_Final_Metrics junta (append) el resultado real (Compute_Audit_Metrics,
// 0 o 1 item) con el fallback garantizado (Compute_Empty_Fallback_Metrics,
// siempre 1 item) -- entre 1 y 2 items llegan aca. Nos quedamos con el real
// si esta, si no con el fallback, y devolvemos exactamente 1 item para que
// Persist_Scan_Statistics haga un solo POST.
const real = items.find(i => !i.json.isFallback);
return [real || items[0]];

