return [
  { json: { severity: 'low' } },
  { json: { severity: 'medium' } },
  { json: { severity: 'high' } },
  { json: { severity: 'critical' } },
];

const SUPPORTED_ECOSYSTEMS = ['npm','pip','maven','nuget','rust','go','composer','rubygems'];
const bySeverity = { low: [], medium: [], high: [], critical: [] };
const seen = new Set();

for (const item of items) {
  const data = item.json;
  const severity = String(data.severity || '').toLowerCase();
  if (!bySeverity[severity]) continue;
  const pkg = data.vulnerabilities && data.vulnerabilities.package;
  if (!pkg || !pkg.name || !pkg.ecosystem) continue;
  const ecosystem = pkg.ecosystem.toLowerCase();
  if (!SUPPORTED_ECOSYSTEMS.includes(ecosystem)) continue;
  const key = pkg.name.toLowerCase() + '|' + ecosystem;
  if (seen.has(key)) continue;
  seen.add(key);

  let version = '0.0.1';
  const range = String((data.vulnerabilities && data.vulnerabilities.vulnerable_version_range) || '');
  const match = range.match(/\d+[\d.]*/);
  if (match) version = match[0].replace(/\.$/, '');

  bySeverity[severity].push({
    software: pkg.name.toLowerCase(),
    ecosystem,
    version,
    severity,
    ghsaId: data.ghsa_id || null,
    cveId: data.cve_id || null,
  });
}

return [{ json: { bySeverity } }];

const { bySeverity } = items[0].json;
const severities = ['low', 'medium', 'high', 'critical'];

function randomFrom(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

const picked = [];
const pickedKeys = new Set();

for (const sev of severities) {
  const pool = bySeverity[sev] || [];
  if (pool.length === 0) continue;
  const candidate = randomFrom(pool);
  const key = candidate.software + '|' + candidate.ecosystem;
  if (pickedKeys.has(key)) continue;
  picked.push(candidate);
  pickedKeys.add(key);
}

const remaining = severities
  .flatMap(sev => bySeverity[sev] || [])
  .filter(c => !pickedKeys.has(c.software + '|' + c.ecosystem));

while (picked.length < 5 && remaining.length > 0) {
  const idx = Math.floor(Math.random() * remaining.length);
  const candidate = remaining.splice(idx, 1)[0];
  const key = candidate.software + '|' + candidate.ecosystem;
  if (pickedKeys.has(key)) continue;
  picked.push(candidate);
  pickedKeys.add(key);
}

if (picked.length < 5) {
  throw new Error(`Solo se encontraron ${picked.length} paquetes candidatos distintos (se necesitan 5) -- reintentar.`);
}

const hostName = 'Host Inyectado ' + new Date().toISOString().replace(/[:.]/g, '-');
const environmentId = Math.floor(Math.random() * 3) + 1;

return [{
  json: {
    hostName,
    environmentId,
    components: picked.slice(0, 5),
  }
}];

const components = $('Pick_5_Balanced').first().json.components;
const hostId = items[0].json.id;
return components.map(c => ({ json: { ...c, assetId: hostId } }));

// Secuencial en vez de Merge/Wait: este nodo corre recien despues de que
// Persist_Audit_Findings termino el INSERT (dependencia real de datos, no
// una espera por tiempo). Persist_Audit_Findings devuelve el resultado de
// la query, no los hallazgos -- Consolidate_Audit_Results/Compute_Audit_Metrics
// necesitan los items originales de Risk_Assessment_Engine para las metricas.
return $('Risk_Assessment_Engine').all();
